create procedure dbo.USR_AIA_USP_DATAFORMTEMPLATE_EDITLOAD_REVENUEORIGIN
(
  @ID uniqueidentifier,
  @DATALOADED bit = 0 output,
  @TSLONG bigint = 0 output,
  @FINDERNUMBER bigint = null output,
  @SOURCECODE nvarchar(50) = null output,
  @APPEALID uniqueidentifier = null output,
  @MAILINGID uniqueidentifier = null output,
  @CHANNELCODEID uniqueidentifier = null output
)
as
  set nocount on;

  -- be sure to set these, in case the select returns no rows
  set @DATALOADED = 0
  set @TSLONG = 0

  -- populate the output parameters, which correspond to fields on the form.  Note that
  -- we set @DATALOADED = 1 to indicate that the load was successful.  Otherwise, the system
  -- will display a "no data loaded" message.  Also note that we fetch the TSLONG so that concurrency
  -- can be considered.
  select
    @DATALOADED = 1,
    @TSLONG = TSLONG,
    @FINDERNUMBER = FINDERNUMBER,
    @SOURCECODE = SOURCECODE,
    @APPEALID = APPEALID,
    @MAILINGID = MAILINGID,
    @CHANNELCODEID = CHANNELCODEID
  from
    dbo.RECURRINGGIFTAMENDMENT
  where
    FINANCIALTRANSACTIONID = @ID and
    AMENDMENTTYPECODE = 0 -- Only update "Added" records

  if @FINDERNUMBER = 0
    set @FINDERNUMBER = null;

  return 0;

