create procedure dbo.USR_AIA_USP_DATAFORMTEMPLATE_EDIT_REVENUEORIGIN 
(
  @ID uniqueidentifier,
  @CHANGEAGENTID uniqueidentifier = null,
  @FINDERNUMBER bigint,
  @SOURCECODE nvarchar(50),
  @APPEALID uniqueidentifier,
  @MAILINGID uniqueidentifier,
  @CHANNELCODEID uniqueidentifier
)
as

  set nocount on;

  if @CHANGEAGENTID is null  
    exec dbo.USP_CHANGEAGENT_GETORCREATECHANGEAGENT @CHANGEAGENTID output

  declare @CURRENTDATE datetime
  set @CURRENTDATE = getdate()

  begin try
    if @FINDERNUMBER is null
      set @FINDERNUMBER = 0;
    else if @FINDERNUMBER <> 0
    begin
      if dbo.[UFN_MKTFINDERNUMBER_VALIDATE_MOD10](@FINDERNUMBER) = 0
        raiserror('BBERR_FINDERNUMBER_FAILEDCHECKDIGIT', 13, 1);

      if dbo.[UFN_MKTSEGMENTATIONFINDERNUMBER_GETSEGMENTATION](@FINDERNUMBER) is null
        raiserror('BBERR_FINDERNUMBER_INVALID', 13, 1);
    end

    -- Update revenue origin metadata fields where applicable
    update
      RECURRINGGIFTAMENDMENT
    set
      FINDERNUMBER = @FINDERNUMBER,
      SOURCECODE = @SOURCECODE,
      APPEALID = @APPEALID,
      MAILINGID = @MAILINGID,
      CHANNELCODEID = @CHANNELCODEID,
      CHANGEDBYID = @CHANGEAGENTID,
      DATECHANGED = @CURRENTDATE
    where
      FINANCIALTRANSACTIONID = @ID and
      AMENDMENTTYPECODE = 0 -- Only update "Added" records
  end try

  begin catch
    exec dbo.USP_RAISE_ERROR;
    return 1;
  end catch

  return 0;
